// ====== EDIT ME ======
return [{ json: {
  // mode: "mock"  = built-in FAKE reviews (no Etsy / no keys)
  //       "files" = CSV you export yourself into filesFolder (self-hosted)
  //       "sheet" = Google Sheet tab "Reviews" (you paste your own export)
  // Live Etsy / Judge.me / Shopify API pull is OUT OF SCOPE for v0.1.
  mode: "mock",
  // output: "files" = CSV under outputFolder (self-hosted); "sheet" = Google Sheet tabs
  output: "files",
  filesFolder: "/home/node/.n8n-files/review-radar",
  outputFolder: "/home/node/.n8n-files/review-radar",
  // Only ★ ≤ this value feed theme aggregation + Fix Queue (By Review still lists all)
  minStarsForTheme: 3,
  summaryLanguage: "en",   // en | zh
  // themeEngine: "rules" (default, deterministic keywords) | "gemini" (optional HTTP stub; untested live)
  // Gemini free tier has rate limits; themes can be wrong — always read the weekly report yourself.
  themeEngine: "rules",
  geminiModel: "gemini-flash-latest",
}}];

const cfg = $('Config').first().json;
const items = $input.all();
const reviews = [];
for (const it of items) {
  const j = it.json || {};
  // convertToFile / spreadsheetFile parse may put columns on json directly
  const row = j;
  if (!row.listing_id && !row.review_id && !row.text && !row.review) continue;
  reviews.push({
    review_id: String(row.review_id || row.id || ('F' + (reviews.length + 1))),
    listing_id: String(row.listing_id || row.listing || ''),
    listing_title: String(row.listing_title || row.title || row.listing_name || ''),
    stars: Number(row.stars || row.rating || row.star || 0),
    language: row.language || row.lang || '',
    date: String(row.date || row.created_at || ''),
    text: String(row.text || row.review || row.body || row.comment || ''),
  });
}
return [{ json: { reviews, _cfg: cfg, source: 'files', theme_engine: cfg.themeEngine || 'rules' } }];

const cfg = $('Config').first().json;
const items = $input.all();
const reviews = items.map((it, i) => {
  const row = it.json || {};
  return {
    review_id: String(row.review_id || row.id || ('S' + (i + 1))),
    listing_id: String(row.listing_id || row.listing || ''),
    listing_title: String(row.listing_title || row.title || row.listing_name || ''),
    stars: Number(row.stars || row.rating || row.star || 0),
    language: row.language || row.lang || '',
    date: String(row.date || row.created_at || ''),
    text: String(row.text || row.review || row.body || row.comment || ''),
  };
}).filter(r => r.listing_id || r.text);
return [{ json: { reviews, _cfg: cfg, source: 'sheet', theme_engine: cfg.themeEngine || 'rules' } }];

const cfg = $('Config').first().json;
const prev = $input.first().json;
if ((cfg.themeEngine || 'rules').toLowerCase() !== 'gemini') {
  return [{ json: { ...prev, _skip_gemini: true } }];
}
const reviews = (prev.reviews || []).slice(0, 40);
const prompt =
  'Classify each review into themes from: shipping, sizing, quality, description, packaging, other. ' +
  'Return JSON array of {review_id, themes: string[]}. Reviews:\\n' +
  reviews.map(r => `${r.review_id}|★${r.stars}|${(r.text || '').slice(0, 200)}`).join('\\n');
const body = {
  contents: [{ parts: [{ text: prompt }] }],
  generationConfig: { temperature: 0.2, maxOutputTokens: 2048 },
};
return [{ json: {
  ...prev,
  _skip_gemini: false,
  _gemini_url: `https://generativelanguage.googleapis.com/v1beta/models/${cfg.geminiModel || 'gemini-flash-latest'}:generateContent`,
  _gemini_body: body,
}}];

// If Gemini was skipped or failed, keep rule-based compute path via passthrough reviews.
const cfg = $('Config').first().json;
const prep = $('Prep Gemini (optional)').first().json;
const http = $input.first().json || {};
if (prep._skip_gemini) {
  return [{ json: { reviews: prep.reviews, _cfg: cfg, source: prep.source || 'mock', theme_engine: 'rules' } }];
}
let ai_error = '';
let aiMap = null;
try {
  if (http.error || http.message === 'Forbidden' || http.statusCode >= 400) {
    ai_error = String(http.error || http.message || ('HTTP ' + http.statusCode)).slice(0, 200);
  } else {
    const text = http.candidates?.[0]?.content?.parts?.[0]?.text || '';
    const m = text.match(/\[[\s\S]*\]/);
    if (m) aiMap = JSON.parse(m[0]);
    else ai_error = 'No JSON array in Gemini reply';
  }
} catch (e) {
  ai_error = String(e.message || e).slice(0, 200);
}
// Always fall back to rules for reliability; attach AI_ERROR note if any.
// (v0.1 does not override rule themes with Gemini — stub is for structure only / untested live)
return [{ json: {
  reviews: prep.reviews,
  _cfg: cfg,
  source: prep.source || 'mock',
  theme_engine: ai_error ? 'rules' : 'gemini-stub',
  ai_error: ai_error || (aiMap ? '' : 'Gemini reply unused in v0.1; rules applied'),
}}];

const cfg = $('Config').first().json;
const prev = $input.first().json;
return [{ json: { reviews: prev.reviews, _cfg: cfg, source: prev.source || 'mock', theme_engine: 'rules', ai_error: '' } }];

/**
 * Review Radar for Etsy Shops — rule-based theme tagging (no LLM required).
 * Input: { reviews: [...], _cfg: config }
 * Each review: review_id, listing_id, listing_title, stars, language?, text, date?
 *
 * Themes (multi-label OK): shipping | sizing | quality | description | packaging | other
 * Only reviews with stars <= minStarsForTheme (default 3) feed theme aggregation / Fix Queue.
 * Positive 4–5★ are still listed in By Review but do not drive "fix listing" unless they
 * still match a defect keyword AND stars <= minStars (so 4–5★ never enter Fix Queue by default).
 */
const THEME_RULES = [
  {
    theme: 'shipping',
    // delivery / late / lost / tracking / postage
    re: /\b(ship(?:ping|ped|ment)?|deliver(?:y|ed|ies)?|arriv(?:e|ed|al)|transit|tracking|postage|carrier|delay(?:ed)?|late|lost\s+(?:in\s+)?(?:mail|transit|package)|never\s+arriv)\b/i,
  },
  {
    theme: 'sizing',
    re: /\b(siz(?:e|ing|ed)|fits?\b|fit(?:ting)?|too\s+(?:small|large|big|tight|loose)|runs?\s+(?:small|large|big)|size\s*chart|ordered\s+(?:xxs|xs|s|m|l|xl|xxl)\b|waist|length|measure(?:ments?)?)\b/i,
  },
  {
    theme: 'quality',
    re: /\b(qualit(?:y|ies)|cheap|peel(?:ed|ing)?|broke|broken|defect(?:ive|s)?|tear(?:ed|s)?|torn|stitch(?:ing|es)?|material|fell\s+apart|poor\s+quality|flimsy|scratch(?:ed|es)?|crack(?:ed|s)?|damage(?:d)?)\b/i,
  },
  {
    theme: 'description',
    re: /\b(descri(?:ption|bed|bes)|photo(?:s)?|picture(?:s)?|misleading|unclear|not\s+as\s+described|doesn'?t\s+match|dont\s+match|different\s+from|expect(?:ed|ation)|advertis(?:ed|ement))\b/i,
  },
  {
    theme: 'packaging',
    re: /\b(packag(?:e|ing|ed)|box(?:es)?|wrapping|bubble\s*wrap|poorly\s+packed|arrived\s+broken|smashed\s+in\s+(?:the\s+)?box)\b/i,
  },
];

const SUGGESTIONS = {
  shipping: (n) => `Review shipping times / carrier notes — shipping mentioned in ${n} review(s)`,
  sizing: (n) => `Update size chart — sizing mentioned in ${n} review(s)`,
  quality: (n) => `Check materials / QC — quality mentioned in ${n} review(s)`,
  description: (n) => `Clarify listing photos & description — description mentioned in ${n} review(s)`,
  packaging: (n) => `Improve packaging — packaging mentioned in ${n} review(s)`,
  other: (n) => `Read feedback carefully — other themes in ${n} review(s)`,
};

const SUGGESTIONS_ZH = {
  shipping: (n) => `核对发货时效/物流说明 — ${n} 条评论提到物流`,
  sizing: (n) => `更新尺码表 — ${n} 条评论提到尺码`,
  quality: (n) => `检查用料/质检 — ${n} 条评论提到质量`,
  description: (n) => `澄清主图与描述 — ${n} 条评论提到描述不符`,
  packaging: (n) => `改进包装 — ${n} 条评论提到包装`,
  other: (n) => `仔细阅读反馈 — ${n} 条其他主题评论`,
};

function detectLanguage(text) {
  const t = String(text || '');
  if (/[\u4e00-\u9fff]/.test(t)) return 'zh';
  if (/[äöüßÄÖÜ]/.test(t) || /\b(und|nicht|sehr|größe|qualität)\b/i.test(t)) return 'de';
  return 'en';
}

function isSpammy(text) {
  const t = String(text || '').toLowerCase();
  if (!t.trim()) return false;
  if (/(viagra|cialis|casino|crypto\s*giveaway|click\s+here|https?:\/\/\S+\.(ru|tk|xyz))/i.test(t)) return true;
  if ((t.match(/https?:\/\//g) || []).length >= 2) return true;
  return false;
}

function tagThemes(text) {
  const t = String(text || '').trim();
  if (!t) return ['other'];
  if (isSpammy(t)) return ['other'];
  const hits = [];
  for (const rule of THEME_RULES) {
    if (rule.re.test(t)) hits.push(rule.theme);
  }
  return hits.length ? hits : ['other'];
}

function excerpt(text, max) {
  const t = String(text || '').replace(/\s+/g, ' ').trim();
  if (!t) return '(empty)';
  if (t.length <= (max || 80)) return t;
  return t.slice(0, (max || 80) - 1) + '…';
}

function classifyOne(rev, cfg) {
  const stars = Number(rev.stars);
  const text = rev.text == null ? '' : String(rev.text);
  const themes = tagThemes(text);
  const lang = rev.language || detectLanguage(text);
  const short = text.trim().length > 0 && text.trim().length < 4;
  const empty = !text.trim();
  const spam = isSpammy(text);
  return {
    review_id: rev.review_id || '',
    listing_id: rev.listing_id || '',
    listing_title: rev.listing_title || '',
    stars: Number.isFinite(stars) ? stars : '',
    language: lang,
    themes: themes.join('|'),
    themes_list: themes,
    excerpt: excerpt(text, 100),
    text_len: text.length,
    is_empty: empty ? 'yes' : 'no',
    is_short: short ? 'yes' : 'no',
    is_spam: spam ? 'yes' : 'no',
    date: rev.date || '',
  };
}

function buildThemesAndFix(byReview, cfg) {
  const minStars = Number(cfg.minStarsForTheme);
  const cutoff = Number.isFinite(minStars) ? minStars : 3;
  // Only ≤ cutoff stars feed theme aggregation / Fix Queue
  const forFix = byReview.filter((r) => {
    const s = Number(r.stars);
    if (!Number.isFinite(s)) return false;
    if (s > cutoff) return false;
    if (r.is_spam === 'yes') return false;
    return true;
  });

  // theme -> { count, listing_ids: Set, quotes: [] }
  const themeMap = {};
  // listing_id -> { title, themes: { theme: count }, reviews: n, quotes by theme }
  const listingMap = {};

  for (const r of forFix) {
    const themes = r.themes_list && r.themes_list.length ? r.themes_list : String(r.themes || 'other').split('|');
    for (const th of themes) {
      if (!themeMap[th]) themeMap[th] = { theme: th, review_count: 0, listing_ids: new Set(), quotes: [] };
      themeMap[th].review_count += 1;
      if (r.listing_id) themeMap[th].listing_ids.add(r.listing_id);
      if (themeMap[th].quotes.length < 3 && r.excerpt && r.excerpt !== '(empty)') {
        themeMap[th].quotes.push(`[${r.listing_id}] ${r.excerpt}`);
      }
    }
    const lid = r.listing_id || '(unknown)';
    if (!listingMap[lid]) {
      listingMap[lid] = { listing_id: lid, listing_title: r.listing_title || '', theme_counts: {}, review_count: 0, top_quotes: [] };
    }
    listingMap[lid].review_count += 1;
    if (r.listing_title) listingMap[lid].listing_title = r.listing_title;
    for (const th of themes) {
      listingMap[lid].theme_counts[th] = (listingMap[lid].theme_counts[th] || 0) + 1;
    }
    if (listingMap[lid].top_quotes.length < 2 && r.excerpt && r.excerpt !== '(empty)') {
      listingMap[lid].top_quotes.push(r.excerpt);
    }
  }

  const themeRows = Object.values(themeMap)
    .map((t) => ({
      theme: t.theme,
      review_count: t.review_count,
      listing_ids: [...t.listing_ids].sort().join('|'),
      listing_count: t.listing_ids.size,
      sample_quotes: t.quotes.join(' || '),
    }))
    .sort((a, b) => b.review_count - a.review_count || a.theme.localeCompare(b.theme));

  // Fix Queue: rank listings by total theme-hit reviews (recurring complaints)
  const fixRows = Object.values(listingMap)
    .map((L) => {
      const pairs = Object.entries(L.theme_counts).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
      const topTheme = pairs[0] ? pairs[0][0] : 'other';
      const topCount = pairs[0] ? pairs[0][1] : 0;
      const themesStr = pairs.map(([th, c]) => `${th}:${c}`).join('|');
      const suggestion = (SUGGESTIONS[topTheme] || SUGGESTIONS.other)(topCount);
      const suggestion_zh = (SUGGESTIONS_ZH[topTheme] || SUGGESTIONS_ZH.other)(topCount);
      return {
        rank: 0,
        listing_id: L.listing_id,
        listing_title: L.listing_title,
        complaint_reviews: L.review_count,
        top_theme: topTheme,
        top_theme_count: topCount,
        themes: themesStr,
        suggestion,
        suggestion_zh,
        sample_quotes: L.top_quotes.join(' || '),
      };
    })
    .sort((a, b) => b.complaint_reviews - a.complaint_reviews || b.top_theme_count - a.top_theme_count || a.listing_id.localeCompare(b.listing_id));

  fixRows.forEach((r, i) => { r.rank = i + 1; });

  return { themeRows, fixRows, cutoff, forFixCount: forFix.length };
}

function buildSummary(byReview, themeRows, fixRows, cfg, meta) {
  const cutoff = Number(cfg.minStarsForTheme);
  const minS = Number.isFinite(cutoff) ? cutoff : 3;
  const total = byReview.length;
  const spam = byReview.filter((r) => r.is_spam === 'yes').length;
  const empty = byReview.filter((r) => r.is_empty === 'yes').length;
  const topFix = fixRows[0];
  const topThemes = themeRows.slice(0, 3).map((t) => `${t.theme}(${t.review_count})`).join(', ');

  let text_en =
    `Reviewed ${total} reviews (themes from ★≤${minS} only; spam/empty skipped in Fix Queue). ` +
    `Theme hits: ${topThemes || 'none'}. `;
  if (topFix) {
    text_en += `Top listing to fix: ${topFix.listing_title || topFix.listing_id} (${topFix.listing_id}) — ${topFix.suggestion}. `;
  } else {
    text_en += 'No listing needs a fix from this sample. ';
  }
  if (spam) text_en += `Flagged ${spam} spammy review(s). `;
  if (empty) text_en += `${empty} empty/short review(s). `;
  text_en += 'Rule-based tagging only (no LLM). Always read the original reviews before changing a listing.';

  let text_zh =
    `共处理 ${total} 条评论（仅 ★≤${minS} 进入主题归类与「该改哪条」；垃圾/空评不进 Fix Queue）。` +
    `主题：${topThemes || '无'}。`;
  if (topFix) {
    text_zh += `优先改：${topFix.listing_title || topFix.listing_id}（${topFix.listing_id}）— ${topFix.suggestion_zh}。`;
  } else {
    text_zh += '本样本没有需要优先改的 listing。';
  }
  if (spam) text_zh += `标记垃圾评 ${spam} 条。`;
  if (empty) text_zh += `空/极短评 ${empty} 条。`;
  text_zh += '本周报为规则归类，不是法律建议；改 listing 前请人工读完原文。';

  if (meta && meta.ai_error) {
    text_en += ` AI_ERROR: ${meta.ai_error}`;
    text_zh += ` AI_ERROR: ${meta.ai_error}`;
  }
  if (meta && meta.theme_engine) {
    text_en += ` (theme_engine=${meta.theme_engine})`;
  }

  const lang = (cfg.summaryLanguage || 'en').toLowerCase();
  return {
    text_en,
    text_zh,
    summary: lang === 'zh' ? text_zh : text_en,
    total_reviews: total,
    theme_review_count: meta && meta.forFixCount != null ? meta.forFixCount : 0,
    spam_count: spam,
    empty_count: empty,
    top_fix_listing_id: topFix ? topFix.listing_id : '',
    top_fix_theme: topFix ? topFix.top_theme : '',
  };
}

function computeAll(input) {
  const cfg = input._cfg || input.cfg || {};
  const reviews = input.reviews || [];
  const byReview = reviews.map((r) => classifyOne(r, cfg));
  const { themeRows, fixRows, cutoff, forFixCount } = buildThemesAndFix(byReview, cfg);
  const meta = {
    theme_engine: input.theme_engine || cfg.themeEngine || 'rules',
    ai_error: input.ai_error || '',
    forFixCount,
    cutoff,
    source: input.source || 'mock',
  };
  const summary = buildSummary(byReview, themeRows, fixRows, cfg, meta);
  // Strip themes_list from export rows (CSV-friendly)
  const reviewRows = byReview.map(({ themes_list, ...rest }) => rest);
  return {
    reviewRows,
    themeRows,
    fixRows,
    summary,
    _cfg: cfg,
    _meta: meta,
  };
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = {
    THEME_RULES,
    SUGGESTIONS,
    tagThemes,
    classifyOne,
    buildThemesAndFix,
    buildSummary,
    computeAll,
    isSpammy,
    detectLanguage,
  };
}

const item = $input.first().json;
const out = computeAll(item);
return [{ json: out }];

const d = $input.first().json, at = $now.toFormat('yyyy-LL-dd HH:mm');
const rows = (d.reviewRows || []).map(r => ({ ...r, generated_at: at }));
return (rows.length ? rows : [{ review_id: '', note: 'No reviews', generated_at: at }]).map(json => ({ json }));

const d = $input.first().json, at = $now.toFormat('yyyy-LL-dd HH:mm');
const rows = (d.themeRows || []).map(r => ({ ...r, generated_at: at }));
return (rows.length ? rows : [{ theme: '', note: 'No themes', generated_at: at }]).map(json => ({ json }));

const d = $input.first().json, at = $now.toFormat('yyyy-LL-dd HH:mm');
const rows = (d.fixRows || []).map(r => ({ ...r, generated_at: at }));
return (rows.length ? rows : [{ listing_id: '', note: 'Nothing to fix', generated_at: at }]).map(json => ({ json }));

const d = $input.first().json, at = $now.toFormat('yyyy-LL-dd HH:mm');
const s = d.summary || {}, m = d._meta || {};
const rows = [
  { generated_at: at, type: 'summary', language: 'en', item: 'summary_en', detail: s.text_en || s.summary || '' },
  { generated_at: at, type: 'summary', language: 'zh', item: 'summary_zh', detail: s.text_zh || '' },
  { generated_at: at, type: 'counts', language: '', item: 'total_reviews', detail: String(s.total_reviews || 0) },
  { generated_at: at, type: 'counts', language: '', item: 'theme_review_count', detail: String(s.theme_review_count || 0) },
  { generated_at: at, type: 'counts', language: '', item: 'spam_count', detail: String(s.spam_count || 0) },
  { generated_at: at, type: 'counts', language: '', item: 'empty_count', detail: String(s.empty_count || 0) },
  { generated_at: at, type: 'fix', language: '', item: 'top_fix_listing_id', detail: String(s.top_fix_listing_id || '') },
  { generated_at: at, type: 'fix', language: '', item: 'top_fix_theme', detail: String(s.top_fix_theme || '') },
  { generated_at: at, type: 'meta', language: '', item: 'theme_engine', detail: String(m.theme_engine || 'rules') },
];
if (m.ai_error) rows.push({ generated_at: at, type: 'check', language: '', item: 'AI_ERROR', detail: String(m.ai_error).slice(0, 200) });
const primary = ((d._cfg || {}).summaryLanguage || 'en').toLowerCase() === 'zh' ? (s.text_zh || '') : (s.text_en || s.summary || '');
rows.unshift({ generated_at: at, type: 'summary', language: (d._cfg || {}).summaryLanguage || 'en', item: 'summary', detail: primary });
return rows.map(json => ({ json }));
